P=Path(__file__).resolve().parents[1]; root=P;file=P/'data/locations.json';a=json.loads(file.read_text());by={x['slug']:x for x in a};q={x['slug']:x for x in json.loads((root/'research/incoming/island-queue.json').read_text())['items']}
