hashes={hashlib.sha256(f.read_bytes()).hexdigest():f for f in (P/'img').rglob('*') if f.is_file()}
for slug,date,details,note in rows:
 x=by[slug];item=q[slug];im=next(z for z in item['images'] if 'path' in z);data=(root/im['path']).read_bytes();h=hashlib.sha256(data).hexdigest();assert h==im['sha256'];ext='.jpg' if data.startswith(b'\xff\xd8\xff') else '.png';dest=hashes.get(h,P/'img/locations'/('reviewed-'+slug+'-'+h[:12]+ext))
 if h not in hashes:dest.write_bytes(data);hashes[h]=dest
 page=item['url'];old=x.get('image');x.setdefault('gallery',[])
 if old and old['path']!=str(dest.relative_to(P)) and not any(g.get('image',{}).get('path')==old['path'] for g in x['gallery']):x['gallery'].append({'name':'Иллюстрация каталога','url':old.get('source_page',page),'image':old})
 mirror=' Копия moy.su по пути zombicity.info; побайтовая идентичность разных хостов не проверена.' if 'zombicity.info' in im['original_url'] else ''
 x['image']={'path':str(dest.relative_to(P)),'retrieved_from':im['fetch_url'],'attribution':im['original_url'],'source_page':page,'note':note+mirror+' Оригинальный файл без перекодирования; автор и дата создания неизвестны.'}
 if not any(z['url']==page for z in x['sources']):x['sources'].append({'url':page,'label':'Zombie-island: отдельная статья локации'})
 r={'original_id':'moy-island-reviewed-'+slug,'original_category':'Острова','version':'историческая браузерная Зомби Ферма / Зомби Мания','date':date+' — дата в URL; дата редакции неизвестна','fields':{'Доступ и условия':details},'confidence':'Фанатский источник; исторические данные, платформа не уточнена, независимость от ЗомбиСити не установлена.'};x.setdefault('prior_records',[]);x['prior_records']=[z for z in x['prior_records'] if z.get('original_id')!=r['original_id']]+[r]
