x=by['zombicity-island-4508'];item=q['zombicity-island-4508'];im=item['images'][1];data=(root/im['path']).read_bytes();h=hashlib.sha256(data).hexdigest();assert h==im['sha256'];dest=hashes.get(h,P/'img/locations'/('reviewed-zombicity-island-4508-map-'+h[:12]+'.png'))
if h not in hashes:dest.write_bytes(data)
image={'path':str(dest.relative_to(P)),'retrieved_from':im['fetch_url'],'attribution':im['original_url'],'source_page':item['url'],'note':'Карта острова Рио, подписанная в статье. Копия moy.su по пути zombicity.info; побайтовая идентичность разных хостов не проверена. Оригинальный файл без перекодирования; автор и дата создания неизвестны.'}
x['gallery']=[g for g in x['gallery'] if g.get('name')!='Карта острова Рио']+[{'name':'Карта острова Рио','url':item['url'],'image':image}]
file.write_text(json.dumps(a,ensure_ascii=False,indent=2));print('cards',len(rows))
